<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title ?? 'تعاریف' }}</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700&display=swap"><style>body{font-family:Vazirmatn,sans-serif;background:#07111f;color:#e9f3fb;margin:0}.wrap{max-width:1200px;margin:auto;padding:28px}.bar{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.card{background:#0a1b2b;border:1px solid #1b354b;border-radius:16px;padding:18px;margin-bottom:16px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #173047;text-align:right;font-size:12px}a,.btn{color:#6ee7d0;text-decoration:none}.btn,button{background:#12304a;border:1px solid #2a4c66;color:#e9f3fb;border-radius:9px;padding:8px 12px;font-family:inherit;cursor:pointer}input,select,textarea{width:100%;padding:9px;border-radius:9px;border:1px solid #29455d;background:#0d2133;color:#e9f3fb;font-family:inherit}label{display:block;font-size:11px;margin-bottom:5px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.actions{display:flex;gap:6px;align-items:center}.muted{color:#7f97aa;font-size:11px}.flash{padding:10px;border-radius:9px;background:#123c3a;margin-bottom:14px}@media(max-width:700px){.grid{grid-template-columns:1fr}.wrap{padding:16px}table{display:block;overflow:auto;white-space:nowrap}}</style></head><body><main class="wrap">@if(session('success'))<div class="flash">{{ session('success') }}</div>@endif@yield('content')</main></body></html>